  // (a later refresh with a real quote simply replaces this; a manager's manual price always wins)
  if (!prices.WBTC && prices.BTC) { prices.WBTC = { usd: prices.BTC.usd, change24h: prices.BTC.change24h }; src.WBTC = 'derived'; }
  if (!prices.DAI) { const u = prices.USDC && prices.USDC.usd; prices.DAI = { usd: u > 0.97 && u < 1.03 ? u : 1, change24h: null }; src.DAI = 'derived'; }
