// Telegram alerts for the staff group. Plain text only (no markup) so user-supplied text can't inject anything.
// `markup` (optional) is an inline keyboard, e.g. the approve / reject buttons of a detected deposit.
function notifyStaff(env, ectx, text, markup = null) {
  const token = env.TELEGRAM_BOT_TOKEN;
  const ids = String(env.TELEGRAM_CHAT_IDS || '').split(',').map((s) => s.trim()).filter(Boolean);
  if (!token || !ids.length) return Promise.resolve();
  const job = Promise.allSettled(ids.map((chat_id) =>
    fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id, text: String(text).slice(0, 3500), disable_web_page_preview: true, ...(markup ? { reply_markup: markup } : {}) }),
    }).catch(() => null)));
  if (ectx?.waitUntil) ectx.waitUntil(job);
  return job;
}
