  const m = cleanMessage(b);
  if (!(await canSend(env, staff, m.category))) throw forbidden('not_allowed', 'شما اجازه ارسال این نوع پیام را ندارید.');
  const codes = [...new Set(String(b.users || '').toUpperCase().split(/[\s,;،]+/).map((x) => x.trim()).filter(Boolean))];
  if (!codes.length) throw bad('missing_fields', 'کد کاربر را بنویسید (مثلاً SKY-123456).');
  if (codes.length > MAX_RECIPIENTS) throw bad('too_many', `حداکثر ${MAX_RECIPIENTS} گیرنده در هر ارسال.`);
  const found = [];
