    await ensureUserTotp(env);
    const row = await env.DB.prepare('SELECT id, username, password_hash, status, must_change_password, totp_enabled, totp_secret, totp_last_step, recovery_hashes FROM users WHERE username = ? OR email = ?').bind(u, u.toLowerCase()).first();
    let ok = false;
