      let pass = false; const st = await verifyTotp(await decryptSecret(env, row.totp_secret), c, row.totp_last_step);
      if (st) { const up = await env.DB.prepare('UPDATE users SET totp_last_step = ? WHERE id = ? AND totp_last_step < ?').bind(st, row.id, st).run(); pass = up.meta.changes === 1; }
      else { const left = await useRecoveryCode(row.recovery_hashes, c); if (left !== null) { await env.DB.prepare('UPDATE users SET recovery_hashes = ? WHERE id = ?').bind(left, row.id).run(); pass = true; } }
      if (!pass) { await recordFailure(env, 'ip:' + ip); await recordFailure(env, 'u:' + u.toLowerCase()); throw new HttpError(401, 'invalid_2fa', 'The verification code is wrong.'); }
