    if (!u.profile) throw bad('profile_required', 'Complete your identity and address details first.');
    if (TIER_RANK[u.tier] >= TIER_RANK[level]) throw bad('already_verified', 'You already have this level.');
    if (level === 'pro' && u.tier !== 'advanced') throw bad('advanced_first', 'Complete the Advanced level first.');
    const open = await env.DB.prepare("SELECT COUNT(*) AS n FROM kyc_requests WHERE user_id = ? AND status = 'pending'").bind(user.id).first();
