  if (p.address.length < 5 || !TEXT_RE.test(p.address)) throw bad('invalid_address', 'Enter your full residential address.');
  if (p.city.length < 2 || !TEXT_RE.test(p.city)) throw bad('invalid_city', 'Enter your city.');
  if (p.postal_code && !/^[A-Za-z0-9 -]{3,20}$/.test(p.postal_code)) throw bad('invalid_postal_code', 'Enter a valid postal code.');
  if (!/^\+?[0-9 ()-]{6,25}$/.test(p.phone)) throw bad('invalid_phone', 'Enter a valid phone number with country code.');
  return p;
