const HARD_LIST = [{ key: 'iran', name: 'Iran', iso: 'IR', phone: '+98' }, { key: 'north korea', name: 'North Korea', iso: 'KP', phone: '+850' }, { key: 'syria', name: 'Syria', iso: 'SY', phone: '+963' }, { key: 'cuba', name: 'Cuba', iso: 'CU', phone: '+53' }, { key: 'crimea', name: 'Crimea / Donetsk / Luhansk', iso: '', phone: '' }];
const HARD_REGIONS = /\b(crimea|sevastopol|donetsk|luhansk|lugansk)\b/i;
