const ALIAS = { persia: 'iran', 'islamic republic of iran': 'iran', ir: 'iran', irn: 'iran', 'i.r. iran': 'iran', dprk: 'north korea', kp: 'north korea', "democratic people's republic of korea": 'north korea', 'korea, north': 'north korea', 'korea (north)': 'north korea', 'north-korea': 'north korea', 'syrian arab republic': 'syria', sy: 'syria', 'republic of cuba': 'cuba', cu: 'cuba', 'dr congo': 'dr congo' };
