  const ip = String(request?.headers?.get?.('CF-IPCountry') || '').toUpperCase();
  if (ipOn && HARD_ISO.includes(ip)) throw refuse();
  const flags = [];
  for (const [k, label] of [['nationality', 'ملیت'], ['birth_country', 'کشور تولد']]) {
    const v = canon(profile[k]);
    if (blocked.includes(v)) flags.push(`${label}: ${profile[k]}`);
  }
  const phone = String(profile.phone || '').replace(/[\s()-]/g, '');
