  if (doc_type !== 'passport' && ids.length < 2) throw bad('files_required', 'For an ID card or driving licence, attach both the front and the back.');
  if (sel.length && !sel[0].mime.startsWith('image/')) throw bad('invalid_file_type', 'The selfie must be a photo.');
