const { forbidden, bad } = __req("lib/util.js");
const { ensureInboxTable } = __req("lib/inbox.js");
const { twoFactorSatisfied } = __req("lib/usertotp.js");

const AREAS = ['deposit', 'withdraw', 'transfer', 'trade', 'futures', 'earn'];
const NAME = {
  deposit: ['Deposits', 'واریز'], withdraw: ['Withdrawals', 'برداشت'], transfer: ['Internal transfers', 'انتقال داخلی'],
  trade: ['Convert & Spot trading', 'تبدیل و معاملات اسپات'], futures: ['Futures trading', 'معاملات فیوچرز'], earn: ['Earn', 'سرمایه‌گذاری (Earn)'],
};
const areaName = (a, i) => (NAME[a] || [a, a])[i];

