const require2fa = async (env) => (await env.DB.prepare("SELECT value FROM settings WHERE key = 'require_2fa'").first())?.value === '1';
// every admin call needs a signed-in staff member; if the owner made 2FA mandatory, staff without it can only open the 2FA setup
