    const wallets = (await c.env.DB.prepare('SELECT chain, address, idx FROM wallets WHERE user_id = ?').bind(u.id).all()).results;
    const bal = (await getBalances(c.env, u.id)).map((b) => ({ asset: b.asset, available: fmt(b.available, b.asset), locked: fmt(b.locked, b.asset) }));
    const led = (await c.env.DB.prepare('SELECT id, asset, kind, delta_available, delta_locked, note, created_at FROM ledger WHERE user_id = ? ORDER BY id DESC LIMIT 50').bind(u.id).all()).results
      .map((l) => ({ ...l, delta_available: fmt(l.delta_available, l.asset), delta_locked: fmt(l.delta_locked, l.asset) }));
    const documents = (await c.env.DB.prepare('SELECT id, doc_type, side, mime, length(data) AS size FROM id_documents WHERE user_id = ? ORDER BY id').bind(u.id).all()).results;
    const referred = (await c.env.DB.prepare("SELECT id, username, created_at FROM users WHERE json_extract(profile, '$.referrer_code') = ? ORDER BY id DESC LIMIT 200").bind(u.username).all()).results;
    return json({ success: true, user: u, wallets, balances: bal, ledger: led, documents, referred });
