  route('GET', '/api/admin/sanctions', async (c) => {
    need(await S(c), 'manager');
    const q = clip(c.url.searchParams.get('q'), 100);
    const total = (await c.env.DB.prepare('SELECT COUNT(*) AS n FROM sanctioned_addresses').first()).n;
    const r = q
      ? await c.env.DB.prepare('SELECT address_norm, label, source, created_at FROM sanctioned_addresses WHERE address_norm LIKE ? OR label LIKE ? ORDER BY created_at DESC LIMIT 100').bind('%' + q.toLowerCase() + '%', '%' + q + '%').all()
      : await c.env.DB.prepare('SELECT address_norm, label, source, created_at FROM sanctioned_addresses ORDER BY created_at DESC LIMIT 100').all();
    const sources = (await c.env.DB.prepare("SELECT COALESCE(source,'') AS source, COUNT(*) AS n FROM sanctioned_addresses GROUP BY COALESCE(source,'') ORDER BY n DESC LIMIT 50").all()).results;
    return json({ success: true, total, items: r.results, sources });
  });
  route('POST', '/api/admin/sanctions/remove-source', async (c) => {
    const me = await S(c); need(me, 'manager');
    const b = await readJson(c.request);
    const source = String(b.source ?? '').slice(0, 60);
    const r = await c.env.DB.prepare("DELETE FROM sanctioned_addresses WHERE COALESCE(source,'') = ?").bind(source).run();
    await audit(c.env, c.request, me, 'sanctions.remove_source', source || '(بدون منبع)', `${r.meta.changes} addresses`);
    return json({ success: true, removed: r.meta.changes });
  });
  route('POST', '/api/admin/sanctions/bulk', async (c) => {
    const me = await S(c); need(me, 'manager');
    const b = await readJson(c.request, 600000);
    const source = clip(b.source, 60) || 'manual';
    const lines = String(b.text || '').split(/\r?\n/).map((l) => l.trim()).filter((l) => l && !l.startsWith('#')).slice(0, 5000);
    const items = [];
    // the official token contracts (USDT, USDC, ... on every chain) are never "sanctioned wallets": a wrong list entry would flag every customer
    const contracts = new Set(); for (const p of tokenPairs()) { contracts.add(p.contract); contracts.add(p.contract.toLowerCase()); }
    let contractSkipped = 0;
    for (const line of lines) {
      const [addr, ...rest] = line.split(/[,\t;]+|\s{2,}/);
      const a = addr.trim().split(/\s+/)[0];
      if (a.length < 20 || a.length > 100) continue;
      if (contracts.has(a) || contracts.has(a.toLowerCase())) { contractSkipped++; continue; }
      items.push([await normalizeAnyAddress(a), clip(rest.join(' ') || line.slice(a.length), 100), source]);
    }
    if (contracts.size) await c.env.DB.prepare(`DELETE FROM sanctioned_addresses WHERE address_norm IN (${[...contracts].map(() => '?').join(',')})`).bind(...contracts).run();
    for (let i = 0; i < items.length; i += 50) {
      await c.env.DB.batch(items.slice(i, i + 50).map(([a, l, s]) => c.env.DB.prepare('INSERT OR REPLACE INTO sanctioned_addresses (address_norm, label, source, added_by) VALUES (?,?,?,?)').bind(a, l.trim(), s, me.id)));
    }
    await audit(c.env, c.request, me, 'sanctions.bulk_add', source, `${items.length} addresses`);
    return json({ success: true, added: items.length, skipped: lines.length - items.length - contractSkipped, contracts_skipped: contractSkipped });
  });
  route('POST', '/api/admin/sanctions/remove', async (c) => {
    const me = await S(c); need(me, 'manager');
    const a = await normalizeAnyAddress((await readJson(c.request)).address);
    await c.env.DB.prepare('DELETE FROM sanctioned_addresses WHERE address_norm = ?').bind(a).run();
    await audit(c.env, c.request, me, 'sanctions.remove', a);
    return json({ success: true });
  });
