    const subject = clip(b.subject, 120), body = clip(b.body, 2000);
    if (!subject || !body) throw bad('empty', 'Write a subject and a message.');
    const r = await c.env.DB.prepare('INSERT INTO staff_threads (staff_id, to_role, subject) VALUES (?,?,?)').bind(me.id, to, subject).run();
    const id = r.meta.last_row_id;
    await c.env.DB.prepare('INSERT INTO staff_thread_msgs (thread_id, staff_id, body) VALUES (?,?,?)').bind(id, me.id, body).run();
    if (to === 'owner') notifyStaff(c.env, c.ectx, `پیام داخلی از ${me.display_name || me.username}: ${subject}`);
